"""Run from your Codespaces repository: python3 add_dcf.py"""
from pathlib import Path
import re
import sys
import shutil
from datetime import datetime

FILES = {'components/dcf-calculator.tsx': '\'use client\';\nimport { useState } from \'react\';\nimport { calculateDCF, defaults, type Assumptions } from \'@/lib/dcf\';\nimport { Button } from \'@/components/ui/button\';\nimport { Input } from \'@/components/ui/input\';\nimport { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from \'@/components/ui/table\';\n\nconst fields: {key: keyof Assumptions; label: string; unit: string}[] = [\n  {key:\'revenue\',label:\'Starting annual revenue\',unit:\'USD millions\'},\n  {key:\'growth\',label:\'Annual growth · years 1–5\',unit:\'%\'},\n  {key:\'margin\',label:\'Operating margin\',unit:\'% of revenue\'},\n  {key:\'tax\',label:\'Tax rate\',unit:\'% of positive EBIT\'},\n  {key:\'depreciation\',label:\'Depreciation & amortization\',unit:\'% of revenue\'},\n  {key:\'capex\',label:\'Capital expenditures\',unit:\'% of revenue\'},\n  {key:\'workingCapital\',label:\'Operating working capital\',unit:\'% of revenue\'},\n  {key:\'wacc\',label:\'Discount rate · WACC\',unit:\'%\'},\n  {key:\'terminalGrowth\',label:\'Terminal growth\',unit:\'%\'},\n  {key:\'cash\',label:\'Excess cash\',unit:\'USD millions\'},\n  {key:\'debt\',label:\'Debt\',unit:\'USD millions\'},\n  {key:\'shares\',label:\'Diluted shares outstanding\',unit:\'millions\'},\n];\nconst fmt = (n: number) => n.toLocaleString(\'en-US\',{minimumFractionDigits:2,maximumFractionDigits:2});\nconst initial = () => Object.fromEntries(Object.entries(defaults).map(([k,v])=>[k,String(v)])) as Record<keyof Assumptions,string>;\n\nexport default function DCFCalculator() {\n  const [inputs,setInputs] = useState(initial);\n  const a = Object.fromEntries(Object.entries(inputs).map(([k,v])=>[k,v.trim()===\'\'?NaN:Number(v)])) as Assumptions;\n  let result: ReturnType<typeof calculateDCF> | null = null;\n  let error = \'\';\n  try { result = calculateDCF(a); } catch(e) { error = e instanceof Error ? e.message : \'Check the assumptions.\'; }\n  const waccs = [-2,-1,0,1,2].map(offset=>a.wacc+offset);\n  const growths = [-1,-0.5,0,0.5,1].map(offset=>a.terminalGrowth+offset);\n\n  return <div className="space-y-6">\n    <section className="panel p-5 sm:p-6">\n      <div className="flex flex-wrap items-center justify-between gap-4">\n        <div><h2>Five-year DCF model</h2><p className="mt-2 text-sm text-slate-600">Independent educational scenario · fictional starting assumptions · no live data</p></div>\n        <Button variant="outline" onClick={()=>setInputs(initial())}>Reset sample</Button>\n      </div>\n      <p className="my-5 text-sm leading-6 text-slate-600">Enter amounts in USD millions and shares in millions. Assumptions apply to every forecast year; stable growth begins in year 6. This calculator is separate from the company selected on the dashboard. Inputs reset when you leave this module or reload.</p>\n      <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">\n        {fields.map(field=><label key={field.key} htmlFor={`dcf-${field.key}`} className="block text-sm font-medium text-slate-700">\n          {field.label}<span className="mt-1 block text-xs font-normal text-slate-500">{field.unit}</span>\n          <Input className="mt-2 bg-white" id={`dcf-${field.key}`} type="number" step="any" value={inputs[field.key]} onChange={e=>setInputs({...inputs,[field.key]:e.target.value})}/>\n        </label>)}\n      </div>\n    </section>\n    {error && <p role="alert" className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-800">{error}</p>}\n    {result && <>\n      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3" aria-live="polite">\n        {[\n          [\'Enterprise value\',`$${fmt(result.enterprise)}M`],\n          [\'Equity value\',`$${fmt(result.equity)}M`],\n          [\'Estimated value / share\',`$${fmt(result.perShare)}`],\n        ].map(([label,value])=><section className="panel p-5" key={label}><p className="text-sm text-slate-600">{label}</p><p className="mt-3 break-words text-2xl font-semibold text-blue-700">{value}</p></section>)}\n      </div>\n      {result.equity < 0 && <p className="text-sm text-amber-800">The model produces negative equity value. This indicates debt exceeds modeled enterprise value plus cash; it is not a literal negative stock price.</p>}\n      <section className="panel min-w-0 p-5">\n        <h3>Forecast · USD millions</h3><p className="my-3 text-sm text-slate-500">End-of-year discounting; Year 6 supplies terminal cash flow.</p>\n        <Table><TableHeader><TableRow><TableHead>Line item</TableHead>{[1,2,3,4,5,6].map(year=><TableHead className="text-right" key={year}>Year {year}{year===6?\' · terminal\':\'\'}</TableHead>)}</TableRow></TableHeader><TableBody>\n          {([\n            [\'Revenue\',\'revenue\'],[\'Operating profit · EBIT\',\'ebit\'],[\'Cash taxes (subtract)\',\'taxes\'],[\'D&A (add)\',\'depreciation\'],[\'Capital expenditures (subtract)\',\'capex\'],[\'Change in working capital (subtract)\',\'changeWC\'],[\'Unlevered free cash flow\',\'fcf\'],[\'Present value of cash flow\',\'pv\'],\n          ] as const).map(([label,key])=><TableRow key={key}><TableCell className="font-medium">{label}</TableCell>{[...result.years,result.terminalYear].map(row=><TableCell className="text-right tabular-nums" key={row.year}>{row.year===6 && key===\'pv\'?\'—\':fmt(row[key])}</TableCell>)}</TableRow>)}\n        </TableBody></Table>\n      </section>\n      <section className="panel p-5"><h3>Valuation bridge · USD millions</h3><dl className="mt-4 grid grid-cols-1 gap-3 text-sm sm:grid-cols-2">\n        {[\n          [\'PV of years 1–5 cash flows\',result.pvForecast],[\'Terminal value at end of year 5\',result.terminalValue],[\'PV of terminal value\',result.pvTerminal],[\'Enterprise value\',result.enterprise],[\'Add excess cash\',a.cash],[\'Subtract debt\',a.debt],[\'Equity value\',result.equity],\n        ].map(([label,value])=><div className="flex justify-between gap-3 border-b border-slate-100 py-2" key={label}><dt>{label}</dt><dd className="tabular-nums">{fmt(Number(value))}</dd></div>)}\n      </dl><p className="mt-4 text-sm text-slate-600">Equity value ÷ {fmt(a.shares)} million diluted shares = ${fmt(result.perShare)} per share.</p></section>\n      <section className="panel min-w-0 p-5"><h3>Sensitivity · value per share</h3><p className="my-3 text-sm text-slate-500">Rows vary WACC; columns vary terminal growth. The center is your current scenario.</p>\n        <Table><TableHeader><TableRow><TableHead>WACC / growth</TableHead>{growths.map(g=><TableHead className="text-right" key={g}>{fmt(g)}%</TableHead>)}</TableRow></TableHeader><TableBody>{waccs.map((w,i)=><TableRow key={w}><TableCell className="font-medium">{fmt(w)}%</TableCell>{growths.map((g,j)=>{\n          let value = \'—\'; try { value = \'$\'+fmt(calculateDCF({...a,wacc:w,terminalGrowth:g}).perShare); } catch { /* Invalid combinations are intentionally blank. */ }\n          return <TableCell className={`text-right tabular-nums ${i===2 && j===2?\'bg-blue-50 font-bold text-blue-800\':\'\'}`} key={g}>{value}</TableCell>;\n        })}</TableRow>)}</TableBody></Table>\n        <p className="mt-3 text-xs text-slate-500">— indicates invalid assumptions, including WACC ≤ growth or nonpositive terminal cash flow.</p>\n      </section>\n    </>}\n    <section className="panel p-5 text-sm leading-7 text-slate-600"><h3 className="mb-2 text-slate-900">How the model works</h3>\n      <p>FCFF = EBIT − cash taxes + D&A − capital expenditures − change in operating working capital.</p>\n      <p>Terminal value = Year 6 FCFF ÷ (WACC − terminal growth). Enterprise value is the present value of years 1–5 plus the discounted terminal value.</p>\n      <p className="mt-3">Simplifications: constant margins and investment ratios, no loss carryforwards or tax refunds on losses, and no preferred equity, minority interests, or other equity adjustments. Stable-period reinvestment must support the growth you assume. This introductory model is not tailored to banks or insurers.</p>\n      <a className="text-blue-700 underline" href="https://pages.stern.nyu.edu/~adamodar/New_Home_Page/lectures/val.html" target="_blank" rel="noreferrer">Valuation methodology · NYU Stern / Aswath Damodaran</a>\n      <p className="mt-2">Educational estimates only, not investment advice.</p>\n    </section>\n  </div>;\n}\n', 'lib/dcf.ts': "export type Assumptions = {\n  revenue: number; growth: number; margin: number; tax: number;\n  depreciation: number; capex: number; workingCapital: number;\n  wacc: number; terminalGrowth: number; cash: number; debt: number; shares: number;\n};\nexport const defaults: Assumptions = {\n  revenue: 1000, growth: 10, margin: 20, tax: 25, depreciation: 3,\n  capex: 5, workingCapital: 10, wacc: 10, terminalGrowth: 2.5,\n  cash: 100, debt: 200, shares: 100,\n};\nexport function validate(a: Assumptions): string | null {\n  if (Object.values(a).some(v => !Number.isFinite(v))) return 'Enter a number in every field.';\n  if (a.revenue <= 0 || a.shares <= 0) return 'Revenue and diluted shares must be greater than zero.';\n  if (a.growth <= -100 || a.terminalGrowth <= -100) return 'Growth rates must be greater than −100%.';\n  if (a.wacc <= 0 || a.wacc <= a.terminalGrowth) return 'WACC must be positive and greater than terminal growth.';\n  if (a.margin < -100 || a.margin > 100 || a.tax < 0 || a.tax > 100) return 'Margin must be between −100% and 100%; tax between 0% and 100%.';\n  if ([a.depreciation,a.capex,a.workingCapital].some(v => v < 0 || v > 100)) return 'Reinvestment assumptions must be between 0% and 100%.';\n  if (a.cash < 0 || a.debt < 0) return 'Cash and debt cannot be negative.';\n  return null;\n}\n// All company values are USD millions and shares are millions: their ratio is USD/share.\nexport function calculateDCF(a: Assumptions) {\n  const error = validate(a);\n  if (error) throw new Error(error);\n  function project(previous: number, growth: number, year: number) {\n    const revenue = previous * (1 + growth / 100);\n    const ebit = revenue * a.margin / 100;\n    // Simplification: no immediate tax benefit on losses and no loss carryforwards.\n    const taxes = Math.max(ebit, 0) * a.tax / 100;\n    const depreciation = revenue * a.depreciation / 100;\n    const capex = revenue * a.capex / 100;\n    const changeWC = (revenue - previous) * a.workingCapital / 100;\n    const fcf = ebit - taxes + depreciation - capex - changeWC;\n    return { year, revenue, ebit, taxes, depreciation, capex, changeWC, fcf, pv: fcf / (1 + a.wacc / 100) ** year };\n  }\n  const years = [];\n  let previous = a.revenue;\n  for (let year = 1; year <= 5; year++) {\n    const row = project(previous, a.growth, year);\n    years.push(row); previous = row.revenue;\n  }\n  // Recalculate year 6 at stable growth, including its working-capital investment.\n  const terminalYear = project(previous, a.terminalGrowth, 6);\n  if (terminalYear.fcf <= 0) throw new Error('Terminal free cash flow must be positive for this perpetual-growth model. Review operating and reinvestment assumptions.');\n  const terminalValue = terminalYear.fcf / ((a.wacc - a.terminalGrowth) / 100);\n  const pvTerminal = terminalValue / (1 + a.wacc / 100) ** 5;\n  const pvForecast = years.reduce((sum,row) => sum + row.pv, 0);\n  const enterprise = pvForecast + pvTerminal;\n  const equity = enterprise + a.cash - a.debt;\n  const perShare = equity / a.shares;\n  if (![enterprise,equity,perShare,pvTerminal].every(Number.isFinite)) throw new Error('Inputs are too large to calculate. Reduce the assumptions.');\n  return { years, terminalYear, terminalValue, pvTerminal, pvForecast, enterprise, equity, perShare };\n}\n"}

def main():
    root = Path.cwd()
    page = root / 'app/page.tsx'
    if not page.is_file() or not (root / 'package.json').is_file():
        sys.exit('Open a terminal in the website folder containing package.json, then run python3 add_dcf.py again.')
    original = page.read_text()
    if 'DCFCalculator' in original:
        sys.exit('A DCF calculator is already connected. No files were changed.')
    pattern = r'\{module\s*!==\s*0\s*\?\s*\('
    if len(re.findall(pattern, original)) != 1 or 'DCF valuation' not in original:
        sys.exit('The dashboard structure has changed. No files were changed. Ask for help adapting this installer.')
    for filename in FILES:
        if (root / filename).exists():
            sys.exit(f'{filename} already exists. No files were changed; this installer will not overwrite it.')
    directive = re.search(r'([\"\'])use client\1\s*;', original)
    if not directive:
        sys.exit('Could not find the client component header. No files were changed.')
    updated = re.sub(pattern, '{module === 1 ? <DCFCalculator /> : module !== 0 ? (', original, count=1)
    updated = updated[:directive.end()] + '\nimport DCFCalculator from "@/components/dcf-calculator";\n' + updated[directive.end():]
    updated = re.sub(r'\{i\s*>\s*0\s*&&', '{i > 1 &&', updated)
    backup = Path.home() / '.investment-dashboard-backups' / datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    backup.mkdir(parents=True)
    shutil.copy2(page, backup / 'page.tsx')
    created = []
    try:
        for filename, content in FILES.items():
            target = root / filename
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(content)
            created.append(target)
        page.write_text(updated)
    except Exception:
        page.write_text(original)
        for target in created:
            target.unlink(missing_ok=True)
        raise
    print('DCF calculator installed. Your existing page text and branding were preserved.')
    print(f'Original dashboard backup: {backup / "page.tsx"}')
    print('Next: npx tsc --noEmit')
    print('Then open your website and choose DCF valuation.')

if __name__ == '__main__':
    main()
